"""
title: Auto Tool Selector
author: adaovianapinto
author_url: https://openwebui.com/u/adaovianapinto
version: 1.1.0
description: >
    Looks at what the user is asking and automatically enables only the MCP
    servers that are relevant for that message. No need to manually toggle
    MCP tools per chat — the right ones are activated before the model responds.
"""

from pydantic import BaseModel, Field
from typing import Callable, Awaitable, Any, Optional, Dict, List
import json
import re
import ast
import logging
from difflib import SequenceMatcher

from open_webui.models.users import Users
from open_webui.utils.chat import generate_chat_completion
from open_webui.utils.misc import get_last_user_message
from open_webui.utils.task import get_task_model_id

logger = logging.getLogger(__name__)


class Filter:
    class Valves(BaseModel):
        template: str = Field(
            default="""You have access to the following MCP servers:

{{TOOLS}}

Select all MCP servers that are relevant to the user's query. Return ONLY a JSON list of server IDs.
Do not include explanation or surrounding text. If none are relevant, return an empty list [].
Be conservative — only select servers whose purpose clearly matches what the user is asking for."""
        )
        max_history_chars: int = Field(default=500)
        similarity_threshold: float = Field(default=0.85)

    def __init__(self) -> None:
        self.valves = self.Valves()

    async def _emit(
        self,
        __event_emitter__: Callable[[Dict[str, Any]], Awaitable[None]],
        step: str,
        description: str,
        done: bool = False,
    ) -> None:
        await __event_emitter__(
            {
                "type": "status",
                "data": {"step": step, "description": description, "done": done},
            }
        )

    def _get_mcp_entries(
        self,
        __request__: Any,
    ) -> List[Dict[str, str]]:
        try:
            connections = (
                getattr(__request__.app.state.config, "TOOL_SERVER_CONNECTIONS", None)
                or []
            )
        except Exception as e:
            logger.warning(f"Could not read TOOL_SERVER_CONNECTIONS: {e}")
            return []

        entries = []
        seen: set = set()

        for conn in connections:
            if conn.get("type", "") != "mcp":
                continue

            config = conn.get("config", {}) or {}
            if not config.get("enable", conn.get("enabled", True)):
                continue

            info = conn.get("info", {}) or {}
            server_id = info.get("id", "")
            if not server_id or server_id in seen:
                continue
            seen.add(server_id)

            server_name = info.get("name") or server_id
            server_desc = info.get("description") or ""
            description = (
                f"[{server_name}] {server_desc}".strip()
                if server_desc
                else f"[{server_name}]"
            )

            entries.append(
                {"id": f"server:mcp:{server_id}", "description": description}
            )

        return entries

    @staticmethod
    def _summarize_history(messages: List[Dict[str, Any]], max_chars: int) -> str:
        lines = []
        for msg in messages[-10:]:
            role = str(msg.get("role", "")).upper()
            raw = msg.get("content", "")
            if isinstance(raw, list):
                text = " ".join(
                    b.get("text", "")
                    for b in raw
                    if isinstance(b, dict) and b.get("type") == "text"
                )
            else:
                text = str(raw or "")
            text = text.replace("\n", " ").strip()
            if text:
                lines.append(f"{role}: {text}")
        summary = " | ".join(lines)
        return summary[-max_chars:] if len(summary) > max_chars else summary

    @staticmethod
    def _parse_response(content: str) -> List[str]:
        for raw in re.findall(r"\[[\s\S]*?\]", content):
            try:
                parsed = json.loads(raw)
                if isinstance(parsed, list):
                    return [str(x) for x in parsed]
            except json.JSONDecodeError:
                try:
                    parsed = ast.literal_eval(raw)
                    if isinstance(parsed, list):
                        return [str(x) for x in parsed]
                except Exception:
                    continue
        return []

    @staticmethod
    def _dedup(
        tool_ids: List[str], entries: List[Dict[str, str]], threshold: float
    ) -> List[str]:
        normalized = {
            t["id"]: (t.get("description") or t["id"]).lower() for t in entries
        }
        seen: List[str] = []
        result = []
        for tid in tool_ids:
            name = normalized.get(tid, tid.lower())
            if any(SequenceMatcher(None, name, s).ratio() >= threshold for s in seen):
                continue
            result.append(tid)
            seen.append(name)
        return result

    async def inlet(
        self,
        body: Dict[str, Any],
        __event_emitter__: Callable[[Dict[str, Any]], Awaitable[None]],
        __request__: Any,
        __user__: Optional[Dict[str, Any]] = None,
        __model__: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        messages: List[Dict[str, Any]] = body.get("messages", [])
        user_message = get_last_user_message(messages)
        if not user_message:
            return body

        mcp_entries = self._get_mcp_entries(__request__)

        if not mcp_entries:
            await self._emit(
                __event_emitter__, "mcp_scan", "No MCP servers found", done=True
            )
            return body

        names = ", ".join(
            re.sub(r"^\[", "", e["description"].split("]")[0]) for e in mcp_entries
        )
        await self._emit(__event_emitter__, "mcp_scan", f"MCP servers: {names}")

        user_id = __user__.get("id") if __user__ else None
        task_model_id: Optional[str] = None

        try:
            user_obj = await Users.get_user_by_id(user_id) if user_id else None
            model_id = body.get("model")
            models = getattr(__request__.app.state, "MODELS", {})
            task_model_id = get_task_model_id(
                model_id,
                __request__.app.state.config.TASK_MODEL,
                __request__.app.state.config.TASK_MODEL_EXTERNAL,
                models,
            )

            tool_list = "\n".join(
                f"- {e['id']}: {e['description']}" for e in mcp_entries
            )
            system_prompt = self.valves.template.replace("{{TOOLS}}", tool_list)
            history = self._summarize_history(messages, self.valves.max_history_chars)
            prompt = f'History:\n{history}\n\nUser query:\n"""{user_message}"""'

            await self._emit(
                __event_emitter__,
                "selecting",
                f"Asking {task_model_id} to pick MCP servers…",
            )

            response = await generate_chat_completion(
                request=__request__,
                form_data={
                    "model": task_model_id,
                    "messages": [
                        {"role": "system", "content": system_prompt},
                        {"role": "user", "content": prompt},
                    ],
                    "stream": False,
                },
                user=user_obj,
            )
            raw_content = (
                response.get("choices", [{}])[0].get("message", {}).get("content", "")
            )
            selected = self._parse_response(raw_content)

            await self._emit(
                __event_emitter__, "model_raw", f"Model returned: {selected or '[]'}"
            )

            valid_ids = {e["id"] for e in mcp_entries}
            selected = [tid for tid in selected if tid in valid_ids]
            selected = self._dedup(
                selected, mcp_entries, self.valves.similarity_threshold
            )

            if not selected:
                await self._emit(
                    __event_emitter__, "no_match", "No MCP servers matched", done=True
                )
                return body

            existing = list(body.get("tool_ids", []) or [])
            for tid in selected:
                clean = tid.split("|")[0]
                if clean not in existing:
                    existing.append(clean)
            body["tool_ids"] = existing

            selected_names = ", ".join(
                re.sub(r"^\[", "", e["description"].split("]")[0])
                for e in mcp_entries
                if e["id"] in selected
            )
            await self._emit(
                __event_emitter__, "done", f"Enabled: {selected_names}", done=True
            )

        except Exception as e:
            logger.exception(
                f"AutoToolSelector error | user={user_id} | model={task_model_id}"
            )
            await self._emit(__event_emitter__, "error", f"Error: {e}", done=True)

        return body
